/**
 * SSE Stream Service
 *
 * Manages Server-Sent Events (SSE) connections for real-time project updates.
 * Allows Dashboard to subscribe to project state changes without polling.
 *
 * Features:
 * - Project-specific event streaming
 * - Automatic cleanup on disconnect
 * - Heartbeat to keep connections alive
 * - Integration with LogWatcher events
 *
 * @module api/services/SSEStreamService
 */

import type { Response } from 'express';
import type { LogWatcherService } from '../../services/logWatcher/LogWatcherService.js';
import type { WatcherEvent } from '../../services/logWatcher/types.js';
import type { ProjectService } from './ProjectService.js';
import { createLogger } from '../../utils/logger.js';

const logger = createLogger('SSEStreamService');

/**
 * SSE event types that can be sent to clients.
 */
export type SSEEventType = 'state' | 'heartbeat' | 'error' | 'connected';

/**
 * Represents an active SSE connection.
 */
interface SSEConnection {
  /** Project slug this connection is subscribed to */
  projectSlug: string;
  /** Express response object for streaming */
  response: Response;
  /** Timestamp when connection was established */
  connectedAt: Date;
  /** Heartbeat interval ID */
  heartbeatInterval: NodeJS.Timeout;
  /** Event listener for log watcher events */
  eventListener: (event: WatcherEvent) => void;
}

/**
 * Configuration for SSE stream service.
 */
export interface SSEStreamConfig {
  /** Heartbeat interval in milliseconds (default: 30000) */
  heartbeatInterval?: number;
}

/**
 * Service for managing SSE connections to stream project updates.
 *
 * @example
 * ```typescript
 * const sseService = new SSEStreamService(logWatcher, projectService);
 *
 * // In Express route handler:
 * app.get('/api/projects/:slug/stream', async (req, res) => {
 *   await sseService.handleConnection(req.params.slug, res);
 * });
 * ```
 */
export class SSEStreamService {
  private readonly connections: Map<string, SSEConnection[]> = new Map();
  private readonly config: Required<SSEStreamConfig>;

  /**
   * Create a new SSE Stream Service.
   *
   * @param logWatcher - LogWatcher service to subscribe to project events
   * @param projectService - Project service for state computation
   * @param config - Optional configuration
   */
  constructor(
    private readonly logWatcher: LogWatcherService,
    private readonly projectService: ProjectService,
    config: SSEStreamConfig = {}
  ) {
    this.config = {
      heartbeatInterval: config.heartbeatInterval ?? 30000,
    };
  }

  /**
   * Handle a new SSE connection request.
   *
   * Sets up SSE headers, sends initial state, subscribes to events,
   * and manages cleanup on disconnect.
   *
   * @param projectSlug - Project to stream updates for
   * @param res - Express response object
   * @throws Error if project doesn't exist
   */
  async handleConnection(projectSlug: string, res: Response): Promise<void> {
    logger.info({ projectSlug }, 'New SSE connection request');

    // Verify project exists
    const exists = await this.projectService.projectExists(projectSlug);
    if (!exists) {
      this.sendErrorEvent(res, 'Project not found');
      res.end();
      logger.warn({ projectSlug }, 'SSE connection rejected - project not found');
      return;
    }

    // Set SSE headers
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering

    // Disable response timeout
    res.socket?.setTimeout(0);

    // Send initial connected event
    this.sendEvent(res, 'connected', {
      projectSlug,
      timestamp: new Date().toISOString(),
    });

    // Load and send current state
    try {
      const project = await this.projectService.loadProjectWithState(projectSlug);
      this.sendEvent(res, 'state', {
        slug: project.slug,
        status: project.state.status,
        progress: project.state.progress,
        currentFeature: project.state.currentFeature,
        waitingQuestion: project.state.waitingQuestion,
        demoUrl: project.state.demoUrl,
        repoUrl: project.state.repoUrl,
        updatedAt: project.updatedAt,
      });
    } catch (error) {
      logger.error({ projectSlug, error }, 'Failed to load initial project state');
      this.sendErrorEvent(res, 'Failed to load project state');
    }

    // Create event listener for LogWatcher events
    const eventListener = (event: WatcherEvent) => {
      if (event.projectSlug === projectSlug) {
        this.handleLogEvent(projectSlug, event, res);
      }
    };

    // Subscribe to LogWatcher events
    this.logWatcher.on('event', eventListener);

    // Set up heartbeat
    const heartbeatInterval = setInterval(() => {
      this.sendEvent(res, 'heartbeat', {
        timestamp: new Date().toISOString(),
      });
    }, this.config.heartbeatInterval);

    // Store connection
    const connection: SSEConnection = {
      projectSlug,
      response: res,
      connectedAt: new Date(),
      heartbeatInterval,
      eventListener,
    };

    if (!this.connections.has(projectSlug)) {
      this.connections.set(projectSlug, []);
    }
    this.connections.get(projectSlug)!.push(connection);

    logger.info(
      {
        projectSlug,
        totalConnections: this.getTotalConnectionCount(),
        projectConnections: this.connections.get(projectSlug)!.length,
      },
      'SSE connection established'
    );

    // Handle client disconnect
    res.on('close', () => {
      this.cleanup(connection);
      logger.info(
        {
          projectSlug,
          totalConnections: this.getTotalConnectionCount(),
        },
        'SSE connection closed'
      );
    });
  }

  /**
   * Handle a new log event from LogWatcher.
   *
   * Recomputes project state and sends update to all connected clients.
   *
   * @param projectSlug - Project slug
   * @param event - Watcher event
   * @param res - Response to send update to
   */
  private async handleLogEvent(
    projectSlug: string,
    event: WatcherEvent,
    res: Response
  ): Promise<void> {
    logger.debug(
      { projectSlug, eventType: event.event.type },
      'Processing log event for SSE'
    );

    try {
      // Invalidate cache to get fresh state
      this.projectService.invalidateCache(projectSlug);

      // Recompute state
      const project = await this.projectService.loadProjectWithState(projectSlug);

      // Send updated state
      this.sendEvent(res, 'state', {
        slug: project.slug,
        status: project.state.status,
        progress: project.state.progress,
        currentFeature: project.state.currentFeature,
        waitingQuestion: project.state.waitingQuestion,
        demoUrl: project.state.demoUrl,
        repoUrl: project.state.repoUrl,
        updatedAt: project.updatedAt,
      });

      logger.debug(
        {
          projectSlug,
          status: project.state.status,
          progress: project.state.progress,
        },
        'State update sent via SSE'
      );
    } catch (error) {
      logger.error({ projectSlug, error }, 'Failed to compute state for SSE update');
      this.sendErrorEvent(res, 'Failed to compute project state');
    }
  }

  /**
   * Send an SSE event to the client.
   *
   * @param res - Express response object
   * @param eventType - Type of event
   * @param data - Event data (will be JSON stringified)
   */
  private sendEvent(res: Response, eventType: SSEEventType, data: unknown): void {
    try {
      res.write(`event: ${eventType}\n`);
      res.write(`data: ${JSON.stringify(data)}\n\n`);

      // Explicitly flush if available (some environments)
      if (typeof (res as any).flush === 'function') {
        (res as any).flush();
      }
    } catch (error) {
      logger.error({ eventType, error }, 'Failed to send SSE event');
    }
  }

  /**
   * Send an error event to the client.
   *
   * @param res - Express response object
   * @param message - Error message
   */
  private sendErrorEvent(res: Response, message: string): void {
    this.sendEvent(res, 'error', {
      message,
      timestamp: new Date().toISOString(),
    });
  }

  /**
   * Clean up a connection.
   *
   * Removes event listener, clears heartbeat, removes from map.
   *
   * @param connection - Connection to clean up
   */
  private cleanup(connection: SSEConnection): void {
    const { projectSlug, heartbeatInterval, eventListener } = connection;

    // Remove event listener
    this.logWatcher.off('event', eventListener);

    // Clear heartbeat
    clearInterval(heartbeatInterval);

    // Remove from connections map
    const projectConnections = this.connections.get(projectSlug);
    if (projectConnections) {
      const index = projectConnections.indexOf(connection);
      if (index > -1) {
        projectConnections.splice(index, 1);
      }

      // Remove project entry if no more connections
      if (projectConnections.length === 0) {
        this.connections.delete(projectSlug);
      }
    }
  }

  /**
   * Get total number of active connections across all projects.
   */
  getTotalConnectionCount(): number {
    let count = 0;
    for (const connections of this.connections.values()) {
      count += connections.length;
    }
    return count;
  }

  /**
   * Get number of connections for a specific project.
   *
   * @param projectSlug - Project slug
   */
  getProjectConnectionCount(projectSlug: string): number {
    return this.connections.get(projectSlug)?.length ?? 0;
  }

  /**
   * Close all connections for a project.
   *
   * Useful for testing or administrative actions.
   *
   * @param projectSlug - Project slug
   */
  closeProjectConnections(projectSlug: string): void {
    const connections = this.connections.get(projectSlug);
    if (!connections) {
      return;
    }

    logger.info({ projectSlug, count: connections.length }, 'Closing all SSE connections');

    // Clone array since cleanup modifies the original
    const connectionsToClose = [...connections];

    for (const connection of connectionsToClose) {
      connection.response.end();
      this.cleanup(connection);
    }
  }

  /**
   * Close all active connections.
   *
   * Should be called during service shutdown.
   */
  closeAllConnections(): void {
    logger.info({ count: this.getTotalConnectionCount() }, 'Closing all SSE connections');

    const projectSlugs = Array.from(this.connections.keys());

    for (const slug of projectSlugs) {
      this.closeProjectConnections(slug);
    }
  }

  /**
   * Get list of projects with active connections.
   */
  getActiveProjects(): string[] {
    return Array.from(this.connections.keys());
  }
}

