    50→/**
    51→ * Generates a deterministic UUID v4 from a slug for testing.
    52→ * Uses a simple hash-based approach to create consistent UUIDs.
    53→ */
    54→function generateTestUuid(slug: string): string {
    55→  // Simple hash function to generate consistent UUIDs from slugs
    56→  let hash = 0;
    57→  for (let i = 0; i < slug.length; i++) {
    58→    const char = slug.charCodeAt(i);
    59→    hash = ((hash << 5) - hash) + char;
    60→    hash = hash & hash; // Convert to 32bit integer
    61→  }
    62→
    63→  // Convert to hex and pad
    64→  const hex = Math.abs(hash).toString(16).padStart(8, '0');
    65→  // Create a valid UUID v4 format
    66→  return `${hex.substring(0, 8)}-${hex.substring(0, 4)}-4${hex.substring(1, 4)}-a${hex.substring(0, 3)}-${hex.substring(0, 12).padStart(12, '0')}`;
    67→}
    68→
    69→function createProjectFiles(
    70→  workspacePath: string,
    71→  slug: string,
    72→  options: CreateProjectOptions = {}
    73→): void {
    74→  const projectDir = path.join(workspacePath, slug);
    75→  fs.mkdirSync(projectDir, { recursive: true });
    76→
    77→  // Generate a valid UUID from the slug
    78→  const ideaId = options.metadata?.ideaId ?? generateTestUuid(slug);
    79→
    80→  // Default metadata
    81→  const metadata = {
    82→    schemaVersion: 1,
    83→    ideaId,
    84→    slug,
    85→    token: `token-${slug}`,
    86→    createdAt: '2026-01-26T10:00:00Z',
    87→    startedAt: '2026-01-26T10:05:00Z',
    88→    notes: `Test Project: ${slug}`,
    89→    ...options.metadata,
    90→    // Ensure ideaId is set correctly even if overridden
    91→    ...(options.metadata?.ideaId ? { ideaId: options.metadata.ideaId } : { ideaId }),
    92→  };
    93→
    94→  fs.writeFileSync(
    95→    path.join(projectDir, 'booth.project.json'),
    96→    JSON.stringify(metadata, null, 2)
    97→  );
    98→
    99→  // Events (JSONL)
   100→  if (options.events && options.events.length > 0) {
   101→    const lines = options.events.map((e) => JSON.stringify(e));
   102→    fs.writeFileSync(path.join(projectDir, 'booth.log.jsonl'), lines.join('\n') + '\n');
   103→  }
   104→
   105→  // Features
   106→  if (options.features) {
   107→    fs.writeFileSync(
   108→      path.join(projectDir, 'features.json'),
   109→      JSON.stringify(options.features, null, 2)
   110→    );
   111→  }
   112→}
