/**
 * Integration Tests for GET /api/projects
 *
 * These tests validate the complete API flow from HTTP request through
 * ProjectService to file system - without mocking the service layer.
 *
 * @module api/routes/__tests__/projects.integration.test
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import request from 'supertest';
import express, { type Express } from 'express';
import { createProjectRoutes } from '../projects.js';
import { ProjectService } from '../../services/ProjectService.js';
import { ProjectLoader } from '../../services/ProjectLoader.js';
import { ProjectStateCache } from '../../services/ProjectStateCache.js';
import { ProjectDetailEnricher } from '../../services/ProjectDetailEnricher.js';
import type { ProjectRunStatus } from '@utmessa/shared';

// Note: Not mocking logger for integration tests to allow real logging behavior

/**
 * Test utilities
 */

function createTempWorkspace(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'projects-integration-test-'));
}

function cleanupWorkspace(workspacePath: string): void {
  fs.rmSync(workspacePath, { recursive: true, force: true });
}

interface CreateProjectOptions {
  metadata?: Partial<{
    ideaId: string;
    slug: string;
    token: string;
    createdAt: string;
    startedAt: string;
    notes: string;
  }>;
  events?: object[];
  features?: object;
}

/**
 * Generates a deterministic UUID v4 from a slug for testing.
 * Uses a simple hash-based approach to create consistent UUIDs.
 */
function generateTestUuid(slug: string): string {
  // Simple hash function to generate consistent UUIDs from slugs
  let hash = 0;
  for (let i = 0; i < slug.length; i++) {
    const char = slug.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }

  // Convert to hex and pad
  const hex = Math.abs(hash).toString(16).padStart(8, '0');
  // Create a valid UUID v4 format
  return `${hex.substring(0, 8)}-${hex.substring(0, 4)}-4${hex.substring(1, 4)}-a${hex.substring(0, 3)}-${hex.substring(0, 12).padStart(12, '0')}`;
}

function createProjectFiles(
  workspacePath: string,
  slug: string,
  options: CreateProjectOptions = {}
): void {
  const projectDir = path.join(workspacePath, slug);
  fs.mkdirSync(projectDir, { recursive: true });

  // Generate a valid UUID from the slug
  const ideaId = options.metadata?.ideaId ?? generateTestUuid(slug);

  // Default metadata
  const metadata = {
    schemaVersion: 1,
    ideaId,
    slug,
    token: `token-${slug}`,
    createdAt: '2026-01-26T10:00:00Z',
    startedAt: '2026-01-26T10:05:00Z',
    notes: `Test Project: ${slug}`,
    ...options.metadata,
    // Ensure ideaId is set correctly even if overridden
    ...(options.metadata?.ideaId ? { ideaId: options.metadata.ideaId } : { ideaId }),
  };

  fs.writeFileSync(
    path.join(projectDir, 'booth.project.json'),
    JSON.stringify(metadata, null, 2)
  );

  // Events (JSONL)
  if (options.events && options.events.length > 0) {
    const lines = options.events.map((e) => JSON.stringify(e));
    fs.writeFileSync(path.join(projectDir, 'booth.log.jsonl'), lines.join('\n') + '\n');
  }

  // Features
  if (options.features) {
    fs.writeFileSync(
      path.join(projectDir, 'features.json'),
      JSON.stringify(options.features, null, 2)
    );
  }
}

function createRunningProject(
  workspace: string,
  slug: string,
  startedAt = '2026-01-26T10:05:00Z'
): void {
  createProjectFiles(workspace, slug, {
    metadata: { startedAt },
