/**
 * Creates test Express app with real ProjectService
 */
function createTestApp(workspacePath: string, cacheTtl = 5000): Express {
  const loader = new ProjectLoader(workspacePath);
  const cache = new ProjectStateCache(cacheTtl);
  const projectService = new ProjectService(loader, cache);

  const app = express();
  app.use(express.json());
  app.use('/api', createProjectRoutes(projectService));

  return app;
}

/**
 * Creates test Express app with real ProjectService and ProjectDetailEnricher
 */
function createTestAppWithEnricher(workspacePath: string, cacheTtl = 5000): Express {
  const loader = new ProjectLoader(workspacePath);
  const cache = new ProjectStateCache(cacheTtl);
  const projectService = new ProjectService(loader, cache);
  const enricher = new ProjectDetailEnricher(loader);

  const app = express();
  app.use(express.json());
  app.use('/api', createProjectRoutes(projectService, enricher));

  return app;
}

