      expect(response.status).toBe(200);
      const project = response.body.projects[0];
      expect(project.status).toBe('failed');
      // Note: error field is extracted by ProjectService but not included in ProjectSummary
      // The error is used internally; status='failed' indicates the failure state
    });
  });
});

