    it('should have correct content-type header', async () => {
      createRunningProject(workspacePath, 'content-type-test');

      const response = await request(app).get('/api/projects/content-type-test');

      expect(response.headers['content-type']).toMatch(/application\/json/);
    });

    it('should return valid JSON response', async () => {
      createRunningProject(workspacePath, 'json-test');

      const response = await request(app).get('/api/projects/json-test');

      expect(() => JSON.parse(JSON.stringify(response.body))).not.toThrow();
