/**
 * Mock Intake Server
 *
 * Lightweight Express server that implements the Intake API contract.
 * Used for fast, deterministic E2E tests without a real database.
 *
 * Implements:
 * - GET /api/ideas?status=... - List ideas by status
 * - POST /api/ideas/:id/claim - Claim an idea
 * - POST /api/ideas/:id/update - Update idea status/progress
 *
 * @module e2e/helpers/mock-intake-server
 */

import express, { type Express, type Request, type Response, type NextFunction } from 'express';
import type { Idea, IdeaStatus } from '@utmessa/shared';
import { createServer, type Server } from 'http';

/**
 * Mock Intake Server configuration
 */
export interface MockIntakeConfig {
  port?: number;
  apiKey?: string;
}

/**
 * Update request body
 */
interface UpdateRequest {
  status?: IdeaStatus;
  progress?: number;
  currentStep?: string;
  currentFeature?: string;
  waitingQuestion?: string;
  demoUrl?: string;
  repoUrl?: string;
}

/**
 * Claim request body
 */
interface ClaimRequest {
  claimedBy: string;
}

/**
 * Mock Intake Server for E2E testing
 *
 * Stores ideas in memory and implements the Intake API contract.
 * Supports authentication via X-ORCH-KEY header.
 */
export class MockIntakeServer {
  private app: Express;
  private server: Server | null = null;
  private ideas: Map<string, Idea> = new Map();
  private readonly apiKey: string;
  private port: number;
  private updateHistory: Array<{ ideaId: string; update: UpdateRequest; timestamp: Date }> = [];

  constructor(config: MockIntakeConfig = {}) {
    this.apiKey = config.apiKey ?? 'test-api-key';
    this.port = config.port ?? 0; // 0 = random available port
    this.app = this.createApp();
  }

  private createApp(): Express {
    const app = express();
    app.use(express.json());

    // Authentication middleware for protected endpoints
    const authMiddleware = (req: Request, res: Response, next: NextFunction) => {
      const key = req.headers['x-orch-key'];
      if (key !== this.apiKey) {
        res.status(401).json({ error: 'Unauthorized' });
        return;
      }
      next();
    };

    // GET /api/ideas?status=...
    app.get('/api/ideas', authMiddleware, (req: Request, res: Response) => {
      const statusParam = req.query.status as string | undefined;
      let ideas = Array.from(this.ideas.values());

      if (statusParam) {
        const statuses = statusParam.split(',').map((s) => s.trim());
        ideas = ideas.filter((idea) => statuses.includes(idea.status));
      }

      res.json({
        ideas,
        total: ideas.length,
      });
    });

    // POST /api/ideas/:id/claim
    app.post('/api/ideas/:id/claim', authMiddleware, (req: Request, res: Response) => {
      const { id } = req.params;
      const { claimedBy } = req.body as ClaimRequest;

      const idea = this.ideas.get(id);
      if (!idea) {
        res.status(404).json({ error: 'Idea not found' });
        return;
      }

      if (idea.status === 'claimed' || idea.status === 'running') {
        res.status(409).json({ error: 'Idea already claimed' });
        return;
      }

      // Update idea to claimed status
      const claimedIdea: Idea = {
        ...idea,
        status: 'claimed',
        slug: this.generateSlug(idea.title),
        updatedAt: new Date().toISOString(),
      };

      this.ideas.set(id, claimedIdea);

      res.json(claimedIdea);
    });

    // POST /api/ideas/:id/update
    app.post('/api/ideas/:id/update', authMiddleware, (req: Request, res: Response) => {
      const { id } = req.params;
      const update = req.body as UpdateRequest;

      const idea = this.ideas.get(id);
      if (!idea) {
        res.status(404).json({ error: 'Idea not found' });
        return;
      }

      // Track update history
      this.updateHistory.push({ ideaId: id, update, timestamp: new Date() });

      // Apply partial updates
      const updatedIdea: Idea = {
        ...idea,
        ...(update.status && { status: update.status }),
        ...(update.progress !== undefined && { progress: update.progress }),
        ...(update.currentStep && { currentStep: update.currentStep }),
        ...(update.currentFeature && { currentFeature: update.currentFeature }),
        ...(update.waitingQuestion && { waitingQuestion: update.waitingQuestion }),
        ...(update.demoUrl && { demoUrl: update.demoUrl }),
        ...(update.repoUrl && { repoUrl: update.repoUrl }),
        updatedAt: new Date().toISOString(),
      };

      this.ideas.set(id, updatedIdea);

      res.json(updatedIdea);
    });

    // POST /api/ideas/:id/features (optional)
    app.post('/api/ideas/:id/features', authMiddleware, (req: Request, res: Response) => {
      const { id } = req.params;

      const idea = this.ideas.get(id);
      if (!idea) {
        res.status(404).json({ error: 'Idea not found' });
        return;
      }

      res.json({ success: true });
    });

    return app;
  }

  /**
   * Generate URL-friendly slug from title
   */
  private generateSlug(title: string): string {
    return title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      .slice(0, 50);
  }

  /**
   * Start the mock server
   * @returns The URL of the running server
   */
  async start(): Promise<string> {
    return new Promise((resolve) => {
      this.server = createServer(this.app);
      this.server.listen(this.port, () => {
        const address = this.server!.address();
        if (typeof address === 'object' && address) {
          this.port = address.port;
        }
        resolve(`http://localhost:${this.port}`);
      });
    });
  }

  /**
   * Stop the mock server
   */
  async stop(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.server) {
        this.server.close((err) => {
          if (err) reject(err);
          else resolve();
        });
      } else {
        resolve();
      }
    });
  }

  /**
   * Add an idea to the mock database
   */
  addIdea(idea: Idea): void {
    this.ideas.set(idea.id, idea);
  }

  /**
   * Add multiple ideas
   */
  addIdeas(ideas: Idea[]): void {
    for (const idea of ideas) {
      this.addIdea(idea);
    }
  }

  /**
   * Get an idea by ID
   */
  getIdea(id: string): Idea | undefined {
    return this.ideas.get(id);
  }

  /**
   * Get all ideas
   */
  getAllIdeas(): Idea[] {
    return Array.from(this.ideas.values());
  }

  /**
   * Clear all ideas
   */
  clearIdeas(): void {
    this.ideas.clear();
    this.updateHistory = [];
  }

  /**
   * Get update history for verification
   */
  getUpdateHistory(): Array<{ ideaId: string; update: UpdateRequest; timestamp: Date }> {
    return this.updateHistory;
  }

  /**
   * Get the API key for testing
   */
  getApiKey(): string {
    return this.apiKey;
  }

  /**
   * Get the port the server is running on
   */
  getPort(): number {
    return this.port;
  }
}

/**
 * Service Manager
 *
 * Manages starting and stopping the Orchestrator service for E2E tests.
 * Creates isolated workspaces for each test run.
 *
 * @module e2e/helpers/service-manager
 */

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { spawn, type ChildProcess } from 'child_process';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

/**
 * Service Manager configuration
 */
export interface ServiceManagerConfig {
  orchestratorPort?: number;
  intakeUrl?: string;
  intakeApiKey?: string;
  workspacePath?: string;
  logLevel?: string;
}

/**
 * Manages Orchestrator service lifecycle for E2E tests
 */
export class ServiceManager {
  private orchestratorProcess: ChildProcess | null = null;
  private workspacePath: string;
  private orchestratorPort: number;
  private intakeUrl: string;
  private intakeApiKey: string;
  private logLevel: string;
  private ready = false;

  constructor(config: ServiceManagerConfig = {}) {
    this.orchestratorPort = config.orchestratorPort ?? 0;
    this.intakeUrl = config.intakeUrl ?? 'http://localhost:3001';
    this.intakeApiKey = config.intakeApiKey ?? 'test-api-key';
    this.workspacePath =
      config.workspacePath ?? fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-workspace-'));
    this.logLevel = config.logLevel ?? 'silent';
  }

  /**
   * Get path to orchestrator directory
   */
  private getOrchestratorPath(): string {
    // Navigate from packages/e2e/src/helpers to apps/orchestrator
    return path.resolve(__dirname, '../../../../apps/orchestrator');
  }

  /**
   * Start the Orchestrator service
   *
   * @returns Promise that resolves when the service is ready
   */
  async startOrchestrator(): Promise<{ url: string; port: number }> {
    return new Promise((resolve, reject) => {
      const orchestratorPath = this.getOrchestratorPath();

      // Use tsx to run TypeScript directly
      this.orchestratorProcess = spawn(
        'npx',
        ['tsx', 'src/index.ts'],
        {
          cwd: orchestratorPath,
          env: {
            ...process.env,
            PORT: String(this.orchestratorPort),
            INTAKE_URL: this.intakeUrl,
            INTAKE_API_KEY: this.intakeApiKey,
            WORKSPACE_PATH: this.workspacePath,
            LOG_LEVEL: this.logLevel,
            NODE_ENV: 'test',
          },
          stdio: ['ignore', 'pipe', 'pipe'],
        }
      );

      let stdout = '';
      let stderr = '';

      this.orchestratorProcess.stdout?.on('data', (data: Buffer) => {
        stdout += data.toString();

        // Look for the listening message to know the service is ready
        const match = stdout.match(/Server listening on port (\d+)/);
        if (match && !this.ready) {
          this.ready = true;
          this.orchestratorPort = parseInt(match[1], 10);
          resolve({
            url: `http://localhost:${this.orchestratorPort}`,
            port: this.orchestratorPort,
          });
        }
      });

      this.orchestratorProcess.stderr?.on('data', (data: Buffer) => {
        stderr += data.toString();
      });

      this.orchestratorProcess.on('error', (err) => {
        reject(new Error(`Failed to start orchestrator: ${err.message}`));
      });

      this.orchestratorProcess.on('exit', (code) => {
        if (!this.ready) {
          reject(new Error(`Orchestrator exited with code ${code}. Stderr: ${stderr}`));
        }
      });

      // Timeout if service doesn't start
      setTimeout(() => {
        if (!this.ready) {
          this.stop();
          reject(new Error(`Orchestrator failed to start within timeout. Stdout: ${stdout}, Stderr: ${stderr}`));
        }
      }, 30000);
    });
  }

  /**
   * Stop all managed services
   */
  async stop(): Promise<void> {
    if (this.orchestratorProcess) {
      this.orchestratorProcess.kill('SIGTERM');
      this.orchestratorProcess = null;
      this.ready = false;
    }
  }

  /**
   * Get the workspace path
   */
  getWorkspacePath(): string {
    return this.workspacePath;
  }

  /**
   * Clean up workspace directory
   */
  cleanupWorkspace(): void {
    if (this.workspacePath && fs.existsSync(this.workspacePath)) {
      fs.rmSync(this.workspacePath, { recursive: true, force: true });
    }
  }

  /**
   * Create a fresh workspace
   */
  resetWorkspace(): string {
    this.cleanupWorkspace();
    this.workspacePath = fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-workspace-'));
    return this.workspacePath;
  }

  /**
   * Check if orchestrator is running
   */
  isRunning(): boolean {
    return this.ready && this.orchestratorProcess !== null;
  }

  /**
   * Get orchestrator URL
   */
  getOrchestratorUrl(): string {
    return `http://localhost:${this.orchestratorPort}`;
  }
}

/**
 * Create a temporary workspace directory
 */
export function createTempWorkspace(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-workspace-'));
}

/**
 * Clean up a workspace directory
 */
export function cleanupWorkspace(workspacePath: string): void {
  if (workspacePath && fs.existsSync(workspacePath)) {
    fs.rmSync(workspacePath, { recursive: true, force: true });
  }
}

/**
 * SSE Client for E2E Tests
 *
 * Node.js EventSource wrapper for testing Server-Sent Events.
 * Provides promise-based API for waiting for events.
 *
 * @module e2e/helpers/sse-client
 */

import EventSource from 'eventsource';

/**
 * SSE event received from server
 */
export interface SSEEvent<T = unknown> {
  type: string;
  data: T;
  timestamp: Date;
}

/**
 * SSE Client configuration
 */
export interface SSEClientConfig {
  timeout?: number;
}

/**
 * SSE Client for testing real-time updates
 *
 * Wraps EventSource with promise-based API for easier testing.
 */
export class TestSSEClient {
  private eventSource: EventSource | null = null;
  private events: SSEEvent[] = [];
  private eventListeners: Array<(event: SSEEvent) => void> = [];
  private connected = false;
  private readonly timeout: number;

  constructor(config: SSEClientConfig = {}) {
    this.timeout = config.timeout ?? 10000;
  }

  /**
   * Connect to an SSE endpoint
   *
   * @param url - SSE endpoint URL
   * @returns Promise that resolves when connected
   */
  async connect(url: string): Promise<void> {
    return new Promise((resolve, reject) => {
      this.eventSource = new EventSource(url);

      const timeoutId = setTimeout(() => {
        this.close();
        reject(new Error(`SSE connection timeout after ${this.timeout}ms`));
      }, this.timeout);

      this.eventSource.onopen = () => {
        clearTimeout(timeoutId);
        this.connected = true;
        resolve();
      };

      this.eventSource.onerror = (err) => {
        clearTimeout(timeoutId);
        if (!this.connected) {
          reject(new Error(`SSE connection failed: ${JSON.stringify(err)}`));
        }
      };

      // Listen for named events
      this.eventSource.addEventListener('connected', (event) => {
        this.handleEvent('connected', event);
      });

      this.eventSource.addEventListener('state', (event) => {
        this.handleEvent('state', event);
      });

      this.eventSource.addEventListener('heartbeat', (event) => {
        this.handleEvent('heartbeat', event);
      });

      this.eventSource.addEventListener('error', (event) => {
        this.handleEvent('error', event);
      });
    });
  }

  /**
   * Handle received event
   */
  private handleEvent(type: string, event: MessageEvent | Event): void {
    const sseEvent: SSEEvent = {
      type,
      data: 'data' in event ? this.parseData((event as MessageEvent).data) : null,
      timestamp: new Date(),
    };

    this.events.push(sseEvent);

    // Notify listeners
    for (const listener of this.eventListeners) {
      listener(sseEvent);
    }
  }

  /**
   * Parse event data (JSON or string)
   */
  private parseData(data: string): unknown {
    try {
      return JSON.parse(data);
    } catch {
      return data;
    }
  }

  /**
   * Wait for an event of a specific type
   *
   * @param eventType - Event type to wait for
   * @param timeout - Timeout in ms (default: 10000)
   * @returns Promise that resolves with the event
   */
  async waitForEvent<T = unknown>(eventType: string, timeout?: number): Promise<SSEEvent<T>> {
    const waitTimeout = timeout ?? this.timeout;

    // Check if we already have a matching event
    const existing = this.events.find((e) => e.type === eventType);
    if (existing) {
      return existing as SSEEvent<T>;
    }

    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error(`Timeout waiting for event: ${eventType}`));
      }, waitTimeout);

      const listener = (event: SSEEvent) => {
        if (event.type === eventType) {
          clearTimeout(timeoutId);
          this.removeEventListener(listener);
          resolve(event as SSEEvent<T>);
        }
      };

      this.addEventListener(listener);
    });
  }

  /**
   * Wait for N events of a specific type
   *
   * @param eventType - Event type to wait for
   * @param count - Number of events to collect
   * @param timeout - Timeout in ms
   * @returns Promise that resolves with the events
   */
  async waitForEvents<T = unknown>(
    eventType: string,
    count: number,
    timeout?: number
  ): Promise<Array<SSEEvent<T>>> {
    const waitTimeout = timeout ?? this.timeout * count;
    const collected: Array<SSEEvent<T>> = [];

    // Get any existing events
    for (const event of this.events) {
      if (event.type === eventType && collected.length < count) {
        collected.push(event as SSEEvent<T>);
      }
    }

    if (collected.length >= count) {
      return collected.slice(0, count);
    }

    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(
          new Error(`Timeout waiting for ${count} events of type ${eventType}. Got ${collected.length}`)
        );
      }, waitTimeout);

      const listener = (event: SSEEvent) => {
        if (event.type === eventType) {
          collected.push(event as SSEEvent<T>);
          if (collected.length >= count) {
            clearTimeout(timeoutId);
            this.removeEventListener(listener);
            resolve(collected.slice(0, count));
          }
        }
      };

      this.addEventListener(listener);
    });
  }

  /**
   * Add event listener
   */
  addEventListener(listener: (event: SSEEvent) => void): void {
    this.eventListeners.push(listener);
  }

  /**
   * Remove event listener
   */
  removeEventListener(listener: (event: SSEEvent) => void): void {
    const index = this.eventListeners.indexOf(listener);
    if (index > -1) {
      this.eventListeners.splice(index, 1);
    }
  }

  /**
   * Get all received events
   */
  getAllEvents(): SSEEvent[] {
    return [...this.events];
  }

  /**
   * Get events of a specific type
   */
  getEventsByType(type: string): SSEEvent[] {
    return this.events.filter((e) => e.type === type);
  }

  /**
   * Clear received events
   */
  clearEvents(): void {
    this.events = [];
  }

  /**
   * Check if connected
   */
  isConnected(): boolean {
    return this.connected && this.eventSource?.readyState === EventSource.OPEN;
  }

  /**
   * Close the connection
   */
  close(): void {
    if (this.eventSource) {
      this.eventSource.close();
      this.eventSource = null;
      this.connected = false;
    }
  }
}

/**
 * Create a connected SSE client
 *
 * @param url - SSE endpoint URL
 * @returns Connected SSE client
 */
export async function createSSEClient(url: string): Promise<TestSSEClient> {
  const client = new TestSSEClient();
  await client.connect(url);
  return client;
}

/**
 * Test Context
 *
 * Utilities for test isolation and shared test state management.
 * Provides setup/teardown helpers for E2E tests.
 *
 * @module e2e/helpers/test-context
 */

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { MockIntakeServer } from './mock-intake-server.js';
import { ServiceManager, cleanupWorkspace } from './service-manager.js';
import { TestSSEClient } from './sse-client.js';

/**
 * Test context configuration
 */
export interface TestContextConfig {
  startOrchestrator?: boolean;
  orchestratorPort?: number;
  intakePort?: number;
  intakeApiKey?: string;
}

/**
 * Test context state
 */
export interface TestContextState {
  workspacePath: string;
  intakeUrl: string;
  orchestratorUrl: string;
  intakeApiKey: string;
  mockIntake: MockIntakeServer;
  serviceManager: ServiceManager;
  sseClients: TestSSEClient[];
}

/**
 * Create an isolated test context with mock services
 *
 * @param config - Context configuration
 * @returns Test context with mock Intake and optionally Orchestrator
 */
export async function createTestContext(config: TestContextConfig = {}): Promise<TestContextState> {
  const apiKey = config.intakeApiKey ?? 'test-api-key';

  // Create workspace
  const workspacePath = fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-test-'));

  // Start mock Intake server
  const mockIntake = new MockIntakeServer({
    port: config.intakePort ?? 0,
    apiKey,
  });
  const intakeUrl = await mockIntake.start();

  // Create service manager
  const serviceManager = new ServiceManager({
    orchestratorPort: config.orchestratorPort ?? 0,
    intakeUrl,
    intakeApiKey: apiKey,
    workspacePath,
  });

  let orchestratorUrl = '';

  // Optionally start orchestrator
  if (config.startOrchestrator !== false) {
    const result = await serviceManager.startOrchestrator();
    orchestratorUrl = result.url;
  }

  return {
    workspacePath,
    intakeUrl,
    orchestratorUrl,
    intakeApiKey: apiKey,
    mockIntake,
    serviceManager,
    sseClients: [],
  };
}

/**
 * Clean up test context
 *
 * @param context - Test context to clean up
 */
export async function cleanupTestContext(context: TestContextState): Promise<void> {
  // Close all SSE clients
  for (const client of context.sseClients) {
    client.close();
  }

  // Stop orchestrator
  await context.serviceManager.stop();

  // Stop mock Intake
  await context.mockIntake.stop();

  // Clean up workspace
  cleanupWorkspace(context.workspacePath);
}

/**
 * Create a minimal test context (mock Intake only)
 *
 * Use this when testing just the Intake API contract without Orchestrator.
 */
export async function createMinimalContext(): Promise<{
  mockIntake: MockIntakeServer;
  intakeUrl: string;
  cleanup: () => Promise<void>;
}> {
  const mockIntake = new MockIntakeServer();
  const intakeUrl = await mockIntake.start();

  return {
    mockIntake,
    intakeUrl,
    cleanup: async () => {
      await mockIntake.stop();
    },
  };
}

/**
 * Wait for a condition to be true
 *
 * @param condition - Function that returns true when condition is met
 * @param timeout - Maximum wait time in ms
 * @param interval - Check interval in ms
 * @returns Promise that resolves when condition is true
 */
export async function waitFor(
  condition: () => boolean | Promise<boolean>,
  timeout = 5000,
  interval = 100
): Promise<void> {
  const startTime = Date.now();

  while (Date.now() - startTime < timeout) {
    if (await condition()) {
      return;
    }
    await sleep(interval);
  }

  throw new Error(`waitFor timed out after ${timeout}ms`);
}

/**
 * Sleep for a specified duration
 *
 * @param ms - Duration in milliseconds
 */
export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Retry a function until it succeeds or times out
 *
 * @param fn - Function to retry
 * @param maxAttempts - Maximum number of attempts
 * @param delay - Delay between attempts in ms
 * @returns Result of the function
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  delay = 1000
): Promise<T> {
  let lastError: Error | undefined;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
      if (attempt < maxAttempts) {
        await sleep(delay);
      }
    }
  }

  throw lastError ?? new Error('Retry failed');
}

