      const idea = createRunningIdea({
        progress: 50,
        currentFeature: 'F2',
      });
      mockIntake.addIdea(idea);

      // Only update progress, not currentFeature
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
