/**
 * Queue Flow Integration Tests
 *
 * Tests the Orchestrator ↔ Intake queue functionality:
 * - Fetching ideas from Intake queue
 * - Filtering by status
 * - Queue ordering
 *
 * @module e2e/api-tests/queue-flow
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import request from 'supertest';
import { MockIntakeServer } from '../helpers/mock-intake-server.js';
import {
  createSubmittedIdea,
  createReadyIdea,
  createRunningIdea,
  createQueueIdeas,
} from '../fixtures/idea.fixtures.js';

describe('Queue Flow - Orchestrator ↔ Intake', () => {
  let mockIntake: MockIntakeServer;
  let intakeUrl: string;

  beforeAll(async () => {
    mockIntake = new MockIntakeServer({ apiKey: 'test-api-key' });
    intakeUrl = await mockIntake.start();
  });

  afterAll(async () => {
    await mockIntake.stop();
  });

  beforeEach(() => {
    mockIntake.clearIdeas();
  });

  describe('GET /api/ideas - Intake API Contract', () => {
    it('should return empty list when no ideas exist', async () => {
      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(response.status).toBe(200);
      expect(response.body).toEqual({
        ideas: [],
        total: 0,
      });
    });

    it('should return all ideas without filter', async () => {
      const ideas = createQueueIdeas();
      mockIntake.addIdeas(ideas);

      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(response.status).toBe(200);
      expect(response.body.ideas).toHaveLength(3);
      expect(response.body.total).toBe(3);
    });

    it('should filter ideas by single status', async () => {
      mockIntake.addIdea(createSubmittedIdea({ title: 'Submitted 1' }));
      mockIntake.addIdea(createReadyIdea({ title: 'Ready 1' }));
      mockIntake.addIdea(createRunningIdea({ title: 'Running 1' }));

      const response = await request(intakeUrl)
        .get('/api/ideas?status=submitted')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(response.status).toBe(200);
      expect(response.body.ideas).toHaveLength(1);
      expect(response.body.ideas[0].title).toBe('Submitted 1');
    });

    it('should filter ideas by multiple statuses', async () => {
      mockIntake.addIdea(createSubmittedIdea({ title: 'Submitted 1' }));
      mockIntake.addIdea(createReadyIdea({ title: 'Ready 1' }));
      mockIntake.addIdea(createRunningIdea({ title: 'Running 1' }));

      const response = await request(intakeUrl)
        .get('/api/ideas?status=submitted,ready')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(response.status).toBe(200);
      expect(response.body.ideas).toHaveLength(2);
      const titles = response.body.ideas.map((i: { title: string }) => i.title);
      expect(titles).toContain('Submitted 1');
      expect(titles).toContain('Ready 1');
    });

    it('should reject requests without API key', async () => {
      const response = await request(intakeUrl).get('/api/ideas');

      expect(response.status).toBe(401);
      expect(response.body.error).toBe('Unauthorized');
    });

    it('should reject requests with invalid API key', async () => {
      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', 'wrong-key');

      expect(response.status).toBe(401);
    });
  });

  describe('POST /api/ideas/:id/claim - Claim Flow', () => {
    it('should successfully claim a submitted idea', async () => {
      const idea = createSubmittedIdea({ title: 'Recipe App' });
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'orchestrator-1' });

      expect(response.status).toBe(200);
      expect(response.body.status).toBe('claimed');
      expect(response.body.slug).toBe('recipe-app');
      expect(response.body.id).toBe(idea.id);
    });

    it('should return 404 for non-existent idea', async () => {
      const response = await request(intakeUrl)
        .post('/api/ideas/non-existent-id/claim')
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'orchestrator-1' });

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Idea not found');
    });

    it('should return 409 when idea is already claimed', async () => {
      const idea = createSubmittedIdea();
      mockIntake.addIdea(idea);

      // First claim should succeed
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'orchestrator-1' });

      // Second claim should fail
      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'orchestrator-2' });

      expect(response.status).toBe(409);
      expect(response.body.error).toBe('Idea already claimed');
    });

    it('should generate slug from title', async () => {
      const idea = createSubmittedIdea({ title: 'My Awesome App v2.0!' });
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'orchestrator-1' });

      expect(response.status).toBe(200);
      expect(response.body.slug).toBe('my-awesome-app-v2-0');
    });
  });

  describe('POST /api/ideas/:id/update - Status Updates', () => {
    it('should update idea status', async () => {
      const idea = createSubmittedIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ status: 'running' });

      expect(response.status).toBe(200);
      expect(response.body.status).toBe('running');
    });

    it('should update progress and current feature', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          progress: 75,
          currentFeature: 'F3',
        });

      expect(response.status).toBe(200);
      expect(response.body.progress).toBe(75);
      expect(response.body.currentFeature).toBe('F3');
    });

    it('should track update history', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 50 });

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 75 });

      const history = mockIntake.getUpdateHistory();
      expect(history).toHaveLength(2);
      expect(history[0].update.progress).toBe(50);
      expect(history[1].update.progress).toBe(75);
    });

    it('should return 404 for non-existent idea', async () => {
      const response = await request(intakeUrl)
        .post('/api/ideas/non-existent-id/update')
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ status: 'running' });

      expect(response.status).toBe(404);
    });
  });

  describe('Response Schema Validation', () => {
    it('should return all required idea fields', async () => {
      const idea = createSubmittedIdea({
        title: 'Complete Idea',
        problem: 'A complete problem description for testing',
        mustHaves: ['Feature A', 'Feature B'],
      });
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(response.status).toBe(200);
      const returnedIdea = response.body.ideas[0];

      // Required fields
      expect(returnedIdea).toHaveProperty('id');
      expect(returnedIdea).toHaveProperty('token');
      expect(returnedIdea).toHaveProperty('title');
      expect(returnedIdea).toHaveProperty('problem');
      expect(returnedIdea).toHaveProperty('email');
      expect(returnedIdea).toHaveProperty('status');
      expect(returnedIdea).toHaveProperty('createdAt');
      expect(returnedIdea).toHaveProperty('updatedAt');

      // Optional fields
      expect(returnedIdea).toHaveProperty('mustHaves');
    });

    it('should return valid UUID for id', async () => {
      const idea = createSubmittedIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      expect(response.body.ideas[0].id).toMatch(uuidRegex);
    });

    it('should return valid ISO datetime strings', async () => {
      const idea = createSubmittedIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .get('/api/ideas')
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      const returnedIdea = response.body.ideas[0];
      expect(() => new Date(returnedIdea.createdAt)).not.toThrow();
      expect(() => new Date(returnedIdea.updatedAt)).not.toThrow();
    });
  });
});

/**
 * Project Lifecycle Integration Tests
 *
 * Tests the full project lifecycle:
 * - Start POC from idea
 * - Project file creation
 * - State computation
 * - Project listing
 *
 * Note: These tests require both Mock Intake and file system access.
 *
 * @module e2e/api-tests/project-lifecycle
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import request from 'supertest';
import express, { type Express } from 'express';
import { MockIntakeServer } from '../helpers/mock-intake-server.js';
import { createSubmittedIdea, createReadyIdea } from '../fixtures/idea.fixtures.js';
import {
  createRunningProject,
  createWaitingProject,
  createDeployedProject,
  createFailedProject,
} from '../fixtures/project.fixtures.js';

describe('Project Lifecycle - Full Flow', () => {
  let mockIntake: MockIntakeServer;
  let intakeUrl: string;
  let workspacePath: string;

  beforeAll(async () => {
    mockIntake = new MockIntakeServer({ apiKey: 'test-api-key' });
    intakeUrl = await mockIntake.start();
  });

  afterAll(async () => {
    await mockIntake.stop();
  });

  beforeEach(() => {
    mockIntake.clearIdeas();
    // Create fresh workspace for each test
    workspacePath = fs.mkdtempSync(path.join(os.tmpdir(), 'e2e-lifecycle-'));
  });

  afterEach(() => {
    // Cleanup workspace
    if (workspacePath && fs.existsSync(workspacePath)) {
      fs.rmSync(workspacePath, { recursive: true, force: true });
    }
  });

  describe('Project Creation Flow', () => {
    it('should claim idea and create project files', async () => {
      const idea = createSubmittedIdea({ title: 'Recipe App' });
      mockIntake.addIdea(idea);

      // Claim the idea
      const claimResponse = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'test-orchestrator' });

      expect(claimResponse.status).toBe(200);
      expect(claimResponse.body.slug).toBe('recipe-app');

      // Simulate project file creation (what Orchestrator does)
      const projectDir = path.join(workspacePath, claimResponse.body.slug);
      fs.mkdirSync(projectDir, { recursive: true });

      // Create booth.project.json
      const metadata = {
        schemaVersion: 1,
        ideaId: idea.id,
        slug: claimResponse.body.slug,
        token: idea.token,
        createdAt: new Date().toISOString(),
        startedAt: new Date().toISOString(),
      };
      fs.writeFileSync(
        path.join(projectDir, 'booth.project.json'),
        JSON.stringify(metadata, null, 2)
      );

      // Verify files exist
      expect(fs.existsSync(projectDir)).toBe(true);
      expect(fs.existsSync(path.join(projectDir, 'booth.project.json'))).toBe(true);
    });

    it('should track claim in Intake after project creation', async () => {
      const idea = createSubmittedIdea();
      mockIntake.addIdea(idea);

      // Claim
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/claim`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ claimedBy: 'test-orchestrator' });

      // Verify idea status updated
      const fetchResponse = await request(intakeUrl)
        .get(`/api/ideas?status=claimed`)
        .set('X-ORCH-KEY', mockIntake.getApiKey());

      expect(fetchResponse.body.ideas).toHaveLength(1);
      expect(fetchResponse.body.ideas[0].id).toBe(idea.id);
    });
  });

  describe('Project State Computation', () => {
    it('should compute running status from events', () => {
      createRunningProject(workspacePath, 'running-project');

      // Read and verify project metadata
      const metadataPath = path.join(workspacePath, 'running-project', 'booth.project.json');
      const metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
      expect(metadata.slug).toBe('running-project');

      // Read and verify events
      const eventsPath = path.join(workspacePath, 'running-project', 'booth.log.jsonl');
      const events = fs
        .readFileSync(eventsPath, 'utf-8')
        .trim()
        .split('\n')
        .map((line) => JSON.parse(line));

      expect(events.some((e) => e.type === 'JOB_STARTED')).toBe(true);
      expect(events.some((e) => e.type === 'FEATURES_PLANNED')).toBe(true);
    });

    it('should compute waiting status from WAITING_FOR_INPUT event', () => {
      const question = 'What authentication method?';
      createWaitingProject(workspacePath, 'waiting-project', question);

      // Read events
      const eventsPath = path.join(workspacePath, 'waiting-project', 'booth.log.jsonl');
      const events = fs
        .readFileSync(eventsPath, 'utf-8')
        .trim()
        .split('\n')
        .map((line) => JSON.parse(line));

      const waitingEvent = events.find((e) => e.type === 'WAITING_FOR_INPUT');
      expect(waitingEvent).toBeDefined();
      expect(waitingEvent.question).toBe(question);
    });

    it('should compute deployed status from DEPLOY_DONE event', () => {
      const demoUrl = 'https://my-app.example.com';
      createDeployedProject(workspacePath, 'deployed-project', demoUrl);

      // Read events
      const eventsPath = path.join(workspacePath, 'deployed-project', 'booth.log.jsonl');
      const events = fs
        .readFileSync(eventsPath, 'utf-8')
        .trim()
        .split('\n')
        .map((line) => JSON.parse(line));

      const deployEvent = events.find((e) => e.type === 'DEPLOY_DONE');
      expect(deployEvent).toBeDefined();
      expect(deployEvent.url).toBe(demoUrl);
    });

    it('should compute failed status from JOB_FAILED event', () => {
      const reason = 'API rate limit exceeded';
      createFailedProject(workspacePath, 'failed-project', reason);

      // Read events
      const eventsPath = path.join(workspacePath, 'failed-project', 'booth.log.jsonl');
      const events = fs
        .readFileSync(eventsPath, 'utf-8')
        .trim()
        .split('\n')
        .map((line) => JSON.parse(line));

      const failedEvent = events.find((e) => e.type === 'JOB_FAILED');
      expect(failedEvent).toBeDefined();
      expect(failedEvent.reason).toBe(reason);
    });
  });

  describe('Project Progress Computation', () => {
    it('should compute progress as percentage of completed features', () => {
      createRunningProject(workspacePath, 'progress-test', {
        features: [
          { id: 'F1', title: 'Feature 1', status: 'done' },
          { id: 'F2', title: 'Feature 2', status: 'done' },
          { id: 'F3', title: 'Feature 3', status: 'in_progress' },
          { id: 'F4', title: 'Feature 4', status: 'planned' },
        ],
      });

      // Read features
      const featuresPath = path.join(workspacePath, 'progress-test', 'features.json');
      const featuresData = JSON.parse(fs.readFileSync(featuresPath, 'utf-8'));

      const totalFeatures = featuresData.features.length;
      const completedFeatures = featuresData.features.filter(
        (f: { status: string }) => f.status === 'done'
      ).length;

      const progress = Math.round((completedFeatures / totalFeatures) * 100);
      expect(progress).toBe(50); // 2 of 4 features done
    });

    it('should handle project with no features yet', () => {
      // Create project without features.json
      const projectDir = path.join(workspacePath, 'no-features');
      fs.mkdirSync(projectDir, { recursive: true });
      fs.writeFileSync(
        path.join(projectDir, 'booth.project.json'),
        JSON.stringify({
          schemaVersion: 1,
          ideaId: '123e4567-e89b-12d3-a456-426614174000',
          slug: 'no-features',
          token: 'token-123',
          createdAt: new Date().toISOString(),
        })
      );

      // No features.json means progress should be null/0
      expect(fs.existsSync(path.join(projectDir, 'features.json'))).toBe(false);
    });
  });

  describe('Multiple Projects', () => {
    it('should list multiple projects from workspace', () => {
      createRunningProject(workspacePath, 'project-a');
      createDeployedProject(workspacePath, 'project-b');
      createWaitingProject(workspacePath, 'project-c');

      // Read workspace directory
      const entries = fs.readdirSync(workspacePath);
      const projectDirs = entries.filter((entry) => {
        const stat = fs.statSync(path.join(workspacePath, entry));
        return stat.isDirectory();
      });

      expect(projectDirs).toHaveLength(3);
      expect(projectDirs).toContain('project-a');
      expect(projectDirs).toContain('project-b');
      expect(projectDirs).toContain('project-c');
    });

    it('should filter projects by status', () => {
      createRunningProject(workspacePath, 'running-1');
      createRunningProject(workspacePath, 'running-2');
      createDeployedProject(workspacePath, 'deployed-1');
      createFailedProject(workspacePath, 'failed-1');

      // Manually compute statuses
      const projects = fs.readdirSync(workspacePath).map((slug) => {
        const eventsPath = path.join(workspacePath, slug, 'booth.log.jsonl');
        if (!fs.existsSync(eventsPath)) return { slug, status: 'not_started' };

        const events = fs
          .readFileSync(eventsPath, 'utf-8')
          .trim()
          .split('\n')
          .filter(Boolean)
          .map((line) => JSON.parse(line));

        // Compute status from events (simplified)
        const lastEvent = events[events.length - 1];
        if (lastEvent?.type === 'DEPLOY_DONE') return { slug, status: 'deployed' };
        if (lastEvent?.type === 'JOB_FAILED') return { slug, status: 'failed' };
        if (events.some((e) => e.type === 'WAITING_FOR_INPUT')) return { slug, status: 'waiting' };
        if (events.some((e) => e.type === 'JOB_STARTED')) return { slug, status: 'running' };
        return { slug, status: 'not_started' };
      });

      const runningProjects = projects.filter((p) => p.status === 'running');
      expect(runningProjects).toHaveLength(2);

      const deployedProjects = projects.filter((p) => p.status === 'deployed');
      expect(deployedProjects).toHaveLength(1);
    });
  });
});

/**
 * Intake Sync Integration Tests
 *
 * Tests state synchronization from Orchestrator to Intake:
 * - Progress updates
 * - Status transitions
 * - Feature updates
 *
 * @module e2e/api-tests/intake-sync
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import request from 'supertest';
import { MockIntakeServer } from '../helpers/mock-intake-server.js';
import {
  createRunningIdea,
  createWaitingIdea,
  createClaimedIdea,
} from '../fixtures/idea.fixtures.js';

describe('Intake Sync - Orchestrator → Intake', () => {
  let mockIntake: MockIntakeServer;
  let intakeUrl: string;

  beforeAll(async () => {
    mockIntake = new MockIntakeServer({ apiKey: 'test-api-key' });
    intakeUrl = await mockIntake.start();
  });

  afterAll(async () => {
    await mockIntake.stop();
  });

  beforeEach(() => {
    mockIntake.clearIdeas();
  });

  describe('Progress Sync', () => {
    it('should sync progress updates to Intake', async () => {
      const idea = createClaimedIdea();
      mockIntake.addIdea(idea);

      // Simulate Orchestrator progress update
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 25 });

      // Verify in Intake
      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.progress).toBe(25);
    });

    it('should track incremental progress updates', async () => {
      const idea = createRunningIdea({ progress: 0 });
      mockIntake.addIdea(idea);

      // Multiple progress updates
      const progressValues = [10, 25, 50, 75, 100];

      for (const progress of progressValues) {
        await request(intakeUrl)
          .post(`/api/ideas/${idea.id}/update`)
          .set('X-ORCH-KEY', mockIntake.getApiKey())
          .send({ progress });
      }

      // Verify final progress
      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.progress).toBe(100);

      // Verify update history
      const history = mockIntake.getUpdateHistory();
      expect(history).toHaveLength(5);
      expect(history.map((h) => h.update.progress)).toEqual(progressValues);
    });

    it('should sync currentFeature with progress', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      // Update with progress and currentFeature
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          progress: 60,
          currentFeature: 'F3',
        });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.progress).toBe(60);
      expect(ideaAfter?.currentFeature).toBe('F3');
    });
  });

  describe('Status Transitions', () => {
    it('should sync claimed → running transition', async () => {
      const idea = createClaimedIdea();
      mockIntake.addIdea(idea);

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ status: 'running' });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.status).toBe('running');
    });

    it('should sync running → waiting transition with question', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      const question = 'What authentication provider should we use?';
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          status: 'waiting',
          waitingQuestion: question,
        });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.status).toBe('waiting');
      expect(ideaAfter?.waitingQuestion).toBe(question);
    });

    it('should sync waiting → running transition after answer', async () => {
      const idea = createWaitingIdea();
      mockIntake.addIdea(idea);

      // Answer provided, resume running
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ status: 'running' });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.status).toBe('running');
    });

    it('should sync running → deployed transition with URLs', async () => {
      const idea = createRunningIdea({ progress: 100 });
      mockIntake.addIdea(idea);

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          status: 'deployed',
          demoUrl: 'https://demo.example.com',
          repoUrl: 'https://github.com/user/repo',
        });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.status).toBe('deployed');
      expect(ideaAfter?.demoUrl).toBe('https://demo.example.com');
      expect(ideaAfter?.repoUrl).toBe('https://github.com/user/repo');
    });

    it('should sync running → failed transition with error', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          status: 'failed',
          currentStep: 'Build failed: npm install failed',
        });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.status).toBe('failed');
      expect(ideaAfter?.currentStep).toContain('failed');
    });
  });

  describe('Partial Updates', () => {
    it('should only update specified fields', async () => {
      const idea = createRunningIdea({
        progress: 50,
        currentFeature: 'F2',
      });
      mockIntake.addIdea(idea);

      // Only update progress, not currentFeature
      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 75 });

      const ideaAfter = mockIntake.getIdea(idea.id);
      expect(ideaAfter?.progress).toBe(75);
      expect(ideaAfter?.currentFeature).toBe('F2'); // Unchanged
    });

    it('should allow empty update (no-op)', async () => {
      const idea = createRunningIdea();
      const originalUpdatedAt = idea.updatedAt;
      mockIntake.addIdea(idea);

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({});

      const ideaAfter = mockIntake.getIdea(idea.id);
      // updatedAt should be updated even for empty update
      expect(ideaAfter?.updatedAt).not.toBe(originalUpdatedAt);
    });
  });

  describe('Feature Sync', () => {
    it('should sync features to Intake', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/features`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({
          features: [
            { id: 'F1', ideaId: idea.id, featureId: 'F1', title: 'Auth', status: 'done' },
            { id: 'F2', ideaId: idea.id, featureId: 'F2', title: 'Dashboard', status: 'in_progress' },
          ],
        });

      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
    });
  });

  describe('Error Handling', () => {
    it('should handle update to non-existent idea', async () => {
      const response = await request(intakeUrl)
        .post('/api/ideas/non-existent/update')
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 50 });

      expect(response.status).toBe(404);
    });

    it('should handle unauthorized update request', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      const response = await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', 'wrong-key')
        .send({ progress: 50 });

      expect(response.status).toBe(401);
    });
  });

  describe('Update Timestamps', () => {
    it('should update updatedAt on each sync', async () => {
      const idea = createRunningIdea();
      mockIntake.addIdea(idea);

      const beforeUpdate = mockIntake.getIdea(idea.id)?.updatedAt;

      // Small delay to ensure timestamp difference
      await new Promise((r) => setTimeout(r, 10));

      await request(intakeUrl)
        .post(`/api/ideas/${idea.id}/update`)
        .set('X-ORCH-KEY', mockIntake.getApiKey())
        .send({ progress: 50 });

      const afterUpdate = mockIntake.getIdea(idea.id)?.updatedAt;

      expect(new Date(afterUpdate!).getTime()).toBeGreaterThan(new Date(beforeUpdate!).getTime());
    });
  });
});

/**
 * SSE Streaming Integration Tests
 *
 * Tests Server-Sent Events for real-time updates:
 * - Connection establishment
 * - State change events
 * - Heartbeat handling
 * - Multiple client connections
 *
 * Note: These tests use a simple Express SSE endpoint for testing
 * the SSE client behavior, not the full Orchestrator.
 *
 * @module e2e/api-tests/sse-streaming
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest';
import express, { type Express, type Response } from 'express';
import { createServer, type Server } from 'http';
import { TestSSEClient } from '../helpers/sse-client.js';
import { sleep } from '../helpers/test-context.js';

/**
 * Test SSE Server
 *
 * Simple Express server that implements SSE for testing the client.
 */
class TestSSEServer {
  private app: Express;
  private server: Server | null = null;
  private connections: Map<string, Response[]> = new Map();
  private port = 0;

  constructor() {
    this.app = express();
    this.setupRoutes();
  }

  private setupRoutes(): void {
    this.app.get('/stream/:projectSlug', (req, res) => {
      const { projectSlug } = req.params;

      // Set SSE headers
      res.setHeader('Content-Type', 'text/event-stream');
      res.setHeader('Cache-Control', 'no-cache');
      res.setHeader('Connection', 'keep-alive');

      // Add to connections
      if (!this.connections.has(projectSlug)) {
        this.connections.set(projectSlug, []);
      }
      this.connections.get(projectSlug)!.push(res);

      // Send connected event
      this.sendEvent(res, 'connected', {
        projectSlug,
        timestamp: new Date().toISOString(),
      });

      // Send initial state
      this.sendEvent(res, 'state', {
        slug: projectSlug,
        status: 'running',
        progress: 50,
        currentFeature: 'F2',
        waitingQuestion: null,
        demoUrl: null,
        repoUrl: null,
        updatedAt: new Date().toISOString(),
      });

      // Handle disconnect
      res.on('close', () => {
        const connections = this.connections.get(projectSlug);
        if (connections) {
          const index = connections.indexOf(res);
          if (index > -1) {
            connections.splice(index, 1);
          }
        }
      });
    });
  }

  private sendEvent(res: Response, eventType: string, data: unknown): void {
    res.write(`event: ${eventType}\n`);
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  }

  /**
   * Broadcast an event to all connections for a project
   */
  broadcast(projectSlug: string, eventType: string, data: unknown): void {
    const connections = this.connections.get(projectSlug);
    if (connections) {
      for (const res of connections) {
        this.sendEvent(res, eventType, data);
      }
    }
  }

  /**
   * Send heartbeat to all connections
   */
  sendHeartbeat(): void {
    for (const [, connections] of this.connections) {
      for (const res of connections) {
        this.sendEvent(res, 'heartbeat', { timestamp: new Date().toISOString() });
      }
    }
  }

  /**
   * Get connection count for a project
   */
  getConnectionCount(projectSlug: string): number {
    return this.connections.get(projectSlug)?.length ?? 0;
  }

  async start(): Promise<string> {
    return new Promise((resolve) => {
      this.server = createServer(this.app);
      this.server.listen(0, () => {
        const address = this.server!.address();
        if (typeof address === 'object' && address) {
          this.port = address.port;
        }
        resolve(`http://localhost:${this.port}`);
      });
    });
  }

  async stop(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.server) {
        this.server.close((err) => {
          if (err) reject(err);
          else resolve();
        });
      } else {
        resolve();
      }
    });
  }
}

describe('SSE Streaming - Real-time Updates', () => {
  let sseServer: TestSSEServer;
  let serverUrl: string;
  let clients: TestSSEClient[] = [];

  beforeAll(async () => {
    sseServer = new TestSSEServer();
    serverUrl = await sseServer.start();
  });

  afterAll(async () => {
    // Close all clients
    for (const client of clients) {
      client.close();
    }
    await sseServer.stop();
  });

  beforeEach(() => {
    // Close clients from previous test
    for (const client of clients) {
      client.close();
    }
    clients = [];
  });

  describe('Connection Establishment', () => {
    it('should connect to SSE endpoint', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/test-project`);

      expect(client.isConnected()).toBe(true);
    });

    it('should receive connected event on connection', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/my-project`);

      const connectedEvent = await client.waitForEvent('connected');
      expect(connectedEvent.type).toBe('connected');
      expect(connectedEvent.data).toHaveProperty('projectSlug', 'my-project');
      expect(connectedEvent.data).toHaveProperty('timestamp');
    });

    it('should receive initial state on connection', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/initial-state`);

      const stateEvent = await client.waitForEvent('state');
      expect(stateEvent.type).toBe('state');
      expect(stateEvent.data).toHaveProperty('slug', 'initial-state');
      expect(stateEvent.data).toHaveProperty('status', 'running');
      expect(stateEvent.data).toHaveProperty('progress', 50);
    });
  });

  describe('State Updates', () => {
    it('should receive state update events', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/state-updates`);

      // Wait for initial events
      await client.waitForEvent('connected');
      await client.waitForEvent('state');

      // Clear events and wait for broadcast
      client.clearEvents();

      // Broadcast a state update
      sseServer.broadcast('state-updates', 'state', {
        slug: 'state-updates',
        status: 'waiting',
        progress: 75,
        currentFeature: 'F3',
        waitingQuestion: 'What color theme?',
        updatedAt: new Date().toISOString(),
      });

      // Wait for the state event
      const stateEvent = await client.waitForEvent('state');
      expect(stateEvent.data).toHaveProperty('status', 'waiting');
      expect(stateEvent.data).toHaveProperty('progress', 75);
      expect(stateEvent.data).toHaveProperty('waitingQuestion', 'What color theme?');
    });

    it('should receive multiple state updates', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/multi-updates`);

      // Clear initial events
      await sleep(100);
      client.clearEvents();

      // Send multiple updates
      sseServer.broadcast('multi-updates', 'state', { progress: 60 });
      sseServer.broadcast('multi-updates', 'state', { progress: 70 });
      sseServer.broadcast('multi-updates', 'state', { progress: 80 });

      // Wait for all state events
      const events = await client.waitForEvents('state', 3, 5000);
      expect(events).toHaveLength(3);

      const progressValues = events.map((e) => (e.data as { progress: number }).progress);
      expect(progressValues).toEqual([60, 70, 80]);
    });
  });

  describe('Heartbeat', () => {
    it('should receive heartbeat events', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/heartbeat-test`);

      // Clear initial events
      await sleep(50);
      client.clearEvents();

      // Trigger heartbeat
      sseServer.sendHeartbeat();

      const heartbeatEvent = await client.waitForEvent('heartbeat');
      expect(heartbeatEvent.type).toBe('heartbeat');
      expect(heartbeatEvent.data).toHaveProperty('timestamp');
    });
  });

  describe('Multiple Clients', () => {
    it('should support multiple clients for same project', async () => {
      const client1 = new TestSSEClient();
      const client2 = new TestSSEClient();
      clients.push(client1, client2);

      await client1.connect(`${serverUrl}/stream/shared-project`);
      await client2.connect(`${serverUrl}/stream/shared-project`);

      expect(client1.isConnected()).toBe(true);
      expect(client2.isConnected()).toBe(true);

      // Both should be tracked
      expect(sseServer.getConnectionCount('shared-project')).toBe(2);
    });

    it('should broadcast to all connected clients', async () => {
      const client1 = new TestSSEClient();
      const client2 = new TestSSEClient();
      clients.push(client1, client2);

      await client1.connect(`${serverUrl}/stream/broadcast-test`);
      await client2.connect(`${serverUrl}/stream/broadcast-test`);

      // Clear initial events
      await sleep(100);
      client1.clearEvents();
      client2.clearEvents();

      // Broadcast update
      sseServer.broadcast('broadcast-test', 'state', { progress: 90 });

      // Both clients should receive it
      const event1 = await client1.waitForEvent('state');
      const event2 = await client2.waitForEvent('state');

      expect((event1.data as { progress: number }).progress).toBe(90);
      expect((event2.data as { progress: number }).progress).toBe(90);
    });

    it('should isolate clients for different projects', async () => {
      const client1 = new TestSSEClient();
      const client2 = new TestSSEClient();
      clients.push(client1, client2);

      await client1.connect(`${serverUrl}/stream/project-a`);
      await client2.connect(`${serverUrl}/stream/project-b`);

      // Clear initial events
      await sleep(100);
      client1.clearEvents();
      client2.clearEvents();

      // Broadcast to project-a only
      sseServer.broadcast('project-a', 'state', { progress: 100 });

      // Only client1 should receive it
      const event1 = await client1.waitForEvent('state', 1000);
      expect((event1.data as { progress: number }).progress).toBe(100);

      // client2 should have no events
      expect(client2.getEventsByType('state')).toHaveLength(0);
    });
  });

  describe('Disconnection', () => {
    it('should handle client disconnect gracefully', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/disconnect-test`);
      expect(sseServer.getConnectionCount('disconnect-test')).toBe(1);

      // Disconnect
      client.close();

      // Wait for server to process disconnect
      await sleep(50);

      expect(sseServer.getConnectionCount('disconnect-test')).toBe(0);
    });

    it('should report disconnected state after close', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/close-test`);
      expect(client.isConnected()).toBe(true);

      client.close();
      expect(client.isConnected()).toBe(false);
    });
  });

  describe('Event History', () => {
    it('should track all received events', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/history-test`);

      // Wait for initial events
      await sleep(100);

      const events = client.getAllEvents();
      expect(events.length).toBeGreaterThanOrEqual(2); // connected + state

      const eventTypes = events.map((e) => e.type);
      expect(eventTypes).toContain('connected');
      expect(eventTypes).toContain('state');
    });

    it('should filter events by type', async () => {
      const client = new TestSSEClient();
      clients.push(client);

      await client.connect(`${serverUrl}/stream/filter-test`);

      // Send multiple heartbeats
      sseServer.sendHeartbeat();
      sseServer.sendHeartbeat();
      await sleep(100);

      const heartbeats = client.getEventsByType('heartbeat');
      expect(heartbeats.length).toBeGreaterThanOrEqual(2);

      // Each heartbeat should have data
      for (const hb of heartbeats) {
        expect(hb.data).toHaveProperty('timestamp');
      }
    });
  });
});

